// The conformance harness's shared pieces: one case of llhttp's markdown suite
// (test/llhttp_corpus.inc, generated by tools/llhttp_corpus.mjs) and the event
// stream every engine is reduced to, so http_parser, llhttp and the llhttp-backed
// prototype compare line by line.
//
// Normalized events (one per line):
//   begin                      on_message_begin
//   url TEXT / status TEXT     on_url / on_status, consecutive slices joined
//   header FIELD: VALUE        one header line: the field slices joined, then the value
//                              slices (an absent value is empty)
//   headers v=M/N method=NAME  on_headers_complete (status=CODE for a response)
//   chunk N / chunk_done       on_chunk_header (chunk size) / on_chunk_complete
//   body TEXT                  on_body, consecutive slices joined
//   complete                   on_message_complete
//   pause                      the parser stopped paused; the driver resumes it (written
//                              where it happens, before a header or slice group it splits)
//   upgrade / h2upgrade        the parser stopped for a protocol upgrade (llhttp's
//                              HPE_PAUSED_UPGRADE / HPE_PAUSED_H2_UPGRADE)
//   error                      the parser rejected the input
//   finish=N                   llhttp's finish state after the input (request-finish
//                              and response-finish cases): 0 safe, 1 the message ends
//                              at EOF, 2 EOF here is an error
// TEXT escapes '\' and every byte outside printable ASCII (\xHH).
#ifndef HTTP_PARSER_CONFORMANCE_H
#define HTTP_PARSER_CONFORMANCE_H

#include <cstddef>
#include <cstdio>
#include <string>
#include <string_view>

namespace conformance {

struct Case {
	const char* location;  // llhttp's file:line
	const char* title;     // section > test name
	const char* type;      // "request", "response-lenient-headers", "request-finish", ...
	const char* pause;     // callback that pauses ("on_message_begin", ...) or ""
	int skip_body;         // on_headers_complete returns 1
	std::string_view input;
	const char* expected;  // normalized events
	const char* note;      // llhttp's error offset, code and reason, or ""
};

struct Result {
	std::string events;
	std::string note;  // the engine's error name and offset
};

inline bool is_response(const Case& c) { return std::string_view(c.type).starts_with("response"); }
inline bool is_finish(const Case& c) { return std::string_view(c.type).ends_with("-finish"); }

inline void escape(std::string& out, std::string_view s) {
	for (unsigned char c : s) {
		if (c == '\\') {
			out += "\\\\";
		} else if (c >= 0x20 && c < 0x7f) {
			out += char(c);
		} else {
			char b[5];
			std::snprintf(b, sizeof b, "\\x%02x", c);
			out += b;
		}
	}
}

// Builds the normalized stream from callbacks (see the header comment).
class Events {
public:
	enum Kind { NONE, URL, STATUS, FIELD, VALUE, BODY };

	void span(Kind k, const char* at, size_t n) {
		if (k == FIELD) {
			if (kind_ != FIELD) flush();
			kind_ = FIELD;
			field_.append(at, n);
			return;
		}
		if (k == VALUE) {
			if (kind_ != FIELD && kind_ != VALUE) flush();
			kind_ = VALUE;
			value_.append(at, n);
			return;
		}
		if (kind_ != k) flush();
		kind_ = k;
		buf_.append(at, n);
	}

	void event(std::string_view e) {
		flush();
		out_ += e;
		out_ += '\n';
	}

	// A pause does not end a pending slice group; it is written before it.
	void pause() { out_ += "pause\n"; }

	void flush() {
		switch (kind_) {
			case NONE: return;
			case URL: out_ += "url "; escape(out_, buf_); break;
			case STATUS: out_ += "status "; escape(out_, buf_); break;
			case BODY: out_ += "body "; escape(out_, buf_); break;
			case FIELD:
			case VALUE:
				out_ += "header ";
				escape(out_, field_);
				out_ += ": ";
				escape(out_, value_);
				break;
		}
		out_ += '\n';
		kind_ = NONE;
		buf_.clear();
		field_.clear();
		value_.clear();
	}

	std::string take() {
		flush();
		return std::move(out_);
	}

	// Whether the last event written is e.
	bool last_is(std::string_view e) const {
		if (kind_ != NONE) return false;
		std::string tail = std::string(e) + "\n";
		return out_.size() >= tail.size() && out_.compare(out_.size() - tail.size(), tail.size(), tail) == 0;
	}

	// Drops the last event (used to fold an EOF-time on_message_complete into finish=1).
	bool drop_last(std::string_view e) {
		flush();
		std::string tail = std::string(e) + "\n";
		if (out_.size() >= tail.size() && out_.compare(out_.size() - tail.size(), tail.size(), tail) == 0) {
			out_.resize(out_.size() - tail.size());
			return true;
		}
		return false;
	}

private:
	Kind kind_ = NONE;
	std::string out_, buf_, field_, value_;
};

}  // namespace conformance

#endif
